sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbo: <http://dbpedia.org/ontology/>

SELECT ?film ?director ?birthDate WHERE {
  VALUES ?film { dbr:The_Mystic_Masseur dbr:The_Rewrite }

  # obtain the director, preferring dbp:director
  OPTIONAL { ?film dbp:director ?directorDbp . }
  OPTIONAL { ?film dbo:letter ?dummy . ?film dbo:director ?directorDbo . }  # ensure pattern for dbo:director
  BIND (COALESCE(?directorDbp, ?directorDbo) AS ?director)

  # obtain the director's birth date, preferring dbp:birthDate
  OPTIONAL { ?director dbp:birthDate ?birthDateDbp . }
  OPTIONAL { ?director dbo:birthDate ?birthDateDbo . }
  BIND (COALESCE(? birthDateDbp, ?birthDateDbo) AS ?birthDate)
}
LIMIT 100

